 "content": "def transform(grid):
    """Extend vertical tracks through horizontal bars, changing color at each bar."""
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    horizontal_rows = [r for r in range(h) if sum(v != 0 for v in g[r]) >= 5]
    if not horizontal_rows:
        return g
    last_bar = max(horizontal_rows)

    # Columns with a vertical seed below the horizontal bars are the tracks.
    tracks = [c for c in range(w) if any(g[r][c] != 0 for r in range(last_bar + 1, h))]
    for c in tracks:
        anchors = []
        for r in horizontal_rows:
            value = g[r][c]
            if value:
                anchors.append((r, value))
            elif 0 < c < w - 1 and g[r][c - 1] and g[r][c + 1]:
                # A one-cell gap in a horizontal bar carries the bar's color.
                if g[r][c - 1] == g[r][c + 1]:
                    anchors.append((r, g[r][c - 1]))
        if not anchors:
            continue

        # The seed color is the color of the vertical stroke below the last bar.
        seed_values = [g[r][c] for r in range(last_bar + 1, h) if g[r][c]]
        if not seed_values:
            continue
        seed = seed_values[0]

        # Each bar's color fills upward to the previous bar; the top bar reaches
        # the top edge, while the bottom vertical seed reaches the bottom edge.
        first_r, first_color = anchors[0]
        for r in range(0, first_r + 1):
            g[r][c] = first_color
        for (prev_r, _), (r, color) in zip(anchors, anchors[1:]):
            for rr in range(prev_r + 1, r + 1):
                g[rr][c] = color
        for r in range(anchors[-1][0] + 1, h):
            g[r][c] = seed
    return g
